/* 离线中文任务看板样式（原生 CSS，无外链资源、无字体引用） */

:root {
  --bg: #f4f6fb;
  --panel: #ffffff;
  --border: #dfe3ec;
  --text: #1f2531;
  --muted: #6b7280;
  --primary: #2f6fed;
  --primary-dark: #2456c4;
  --todo: #6b7280;
  --doing: #f0a020;
  --done: #2f9e5f;
  --danger: #d64545;
  --warn-bg: #fdecec;
  --warn-border: #e79a9a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", "Noto Sans CJK SC", sans-serif;
  font-size: 15px;
  line-height: 1.6;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 22px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}

.topbar h1 { font-size: 20px; margin: 0; }

.topbar-actions { display: flex; gap: 10px; }

.layout {
  max-width: 1180px;
  margin: 0 auto;
  padding: 18px 22px 40px;
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
}

.panel h2 { font-size: 16px; margin: 0 0 12px; }

.warning-banner {
  max-width: 1180px;
  margin: 14px auto 0;
  padding: 12px 16px;
  background: var(--warn-bg);
  border: 1px solid var(--warn-border);
  border-left: 5px solid var(--danger);
  border-radius: 8px;
  color: #8a1f1f;
  white-space: pre-wrap;
  word-break: break-all;
}

.notice {
  max-width: 1180px;
  margin: 14px auto 0;
  padding: 10px 16px;
  background: #eaf4ff;
  border: 1px solid #b7d4f7;
  border-radius: 8px;
  color: #1c4f8f;
}

.field { display: flex; flex-direction: column; gap: 4px; }

.field label { font-size: 13px; color: var(--muted); }

input[type="text"], select {
  padding: 7px 9px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 14px;
  font-family: inherit;
  background: #fff;
  color: var(--text);
}

input[type="text"]:focus, select:focus { outline: 2px solid rgba(47, 111, 237, 0.35); }

.btn {
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
}

.btn:hover { background: #f0f3fa; }

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn-primary:hover { background: var(--primary-dark); }

.btn-danger { color: var(--danger); border-color: #eec3c3; }

.btn-danger:hover { background: #fdecec; }

.btn-small { padding: 4px 9px; font-size: 13px; }

.form-error { color: var(--danger); font-size: 13px; min-height: 18px; }

.form-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 12px;
  flex-wrap: wrap;
}

#create-form { display: grid; grid-template-columns: 2fr 1fr 2fr; gap: 12px; align-items: end; }

.filter-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }

.stats-row { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 8px; }

.stat {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: #f2f5fb;
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 13px;
}

.stat b { font-weight: 600; }

.board {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
}

.column {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px;
  min-height: 180px;
}

.column h2 {
  font-size: 15px;
  margin: 0 0 10px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--border);
}

.column-todo h2 { border-bottom-color: var(--todo); }
.column-doing h2 { border-bottom-color: var(--doing); }
.column-done h2 { border-bottom-color: var(--done); }

.card-list { display: flex; flex-direction: column; gap: 10px; }

.card {
  border: 1px solid var(--border);
  border-left: 4px solid var(--todo);
  border-radius: 8px;
  padding: 10px 12px;
  background: #fff;
}

.card.priority-high { border-left-color: var(--danger); }
.card.priority-medium { border-left-color: var(--doing); }
.card.priority-low { border-left-color: #9aa3b2; }

.card-title {
  font-size: 15px;
  margin: 0 0 6px;
  word-break: break-word;
  white-space: pre-wrap;
}

.card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 8px;
}

.badge {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: #f7f9fc;
}

.badge-priority-high { color: var(--danger); border-color: #eec3c3; background: #fdecec; }
.badge-priority-medium { color: #9a6a00; border-color: #f0dcae; background: #fdf6e3; }
.badge-priority-low { color: #4b5563; }

.tag {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 4px;
  background: #eef2fb;
  border: 1px solid #d8e1f5;
  color: #34538c;
  font-size: 12px;
}

.card-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }

.card-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }

.card-actions select { padding: 4px 6px; font-size: 13px; }

.empty { color: var(--muted); font-size: 13px; margin: 6px 0; }

.modal {
  position: fixed;
  inset: 0;
  background: rgba(24, 30, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.modal[hidden] { display: none; }

.modal-card {
  background: #fff;
  border-radius: 10px;
  padding: 18px 20px;
  width: min(520px, 100%);
  border: 1px solid var(--border);
}

.modal-card h2 { margin: 0 0 12px; font-size: 17px; }

.modal-card .field { margin-bottom: 12px; }

.footer {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 22px 30px;
  color: var(--muted);
  font-size: 13px;
}

@media (max-width: 720px) {
  #create-form { grid-template-columns: 1fr; }
}

arguments.content:
'use strict';

/**
 * 交付级测试套件 01：领域逻辑（src/core.js）。
 *
 * 覆盖清单：1（两层的「核心校验」层）、2、3、5、6（核心层）。
 * 只依赖 README 冻结契约与 src/core.js 的导出名；不依赖实现者自我判断。
 * 运行：node --test（自动发现 test/**\/*.test.js）
 */

const test = require('node:test');
const assert = require('node:assert/strict');

const core = require('../src/core.js');

const {
  validateTitle,
  normalizeTags,
  normalizePriority,
  createTask,
  updateTask,
  filterTasks,
  sortTasks,
  computeStats,
} = core;

// ---------------------------------------------------------------------------
// 覆盖 1：标题校验
// ---------------------------------------------------------------------------

test('[覆盖1] validateTitle：空 / 全空白 / 非字符串一律非法，1–200 字符合法', () => {
  assert.equal(validateTitle('任务'), true);
  assert.equal(validateTitle('  边界任务  '), true);
  assert.equal(validateTitle('a'.repeat(200)), true, '200 字符应合法（上界含）');

  assert.equal(validateTitle(''), false);
  assert.equal(validateTitle('   '), false);
  assert.equal(validateTitle('\t'), false);
  assert.equal(validateTitle('\n'), false);
  assert.equal(validateTitle('\t\n\r'), false);
  assert.equal(validateTitle('\u3000'), false, '全角空格 trim 后也应视为空白');

  assert.equal(validateTitle('a'.repeat(201)), false, '201 字符应非法（上界外）');

  assert.equal(validateTitle(null), false);
  assert.equal(validateTitle(undefined), false);
  assert.equal(validateTitle(123), false);
  assert.equal(validateTitle({}), false);
  assert.equal(validateTitle([]), false);
  assert.equal(validateTitle(true), false);
  assert.equal(validateTitle(Symbol('x')), false, 'Symbol 不能抛异常');
});

test('[覆盖1] createTask：空白 / 缺失 / 非字符串标题抛 TITLE_REQUIRED，超长抛 TITLE_TOO_LONG', () => {
  for (const bad of [{}, { title: '' }, { title: '   ' }, { title: '\t\n' }, { title: null },
    { title: 123 }, { title: [] }, { title: {} }, { title: true }]) {
    assert.throws(
      () => createTask(bad),
      (err) => err.code === 'TITLE_REQUIRED',
      `输入 ${JSON.stringify(bad)} 应抛 TITLE_REQUIRED`,
    );
  }
  assert.throws(
    () => createTask({ title: 'a'.repeat(201) }),
    (err) => err.code === 'TITLE_TOO_LONG',
  );
  // 纯字符串入参视为标题
  assert.throws(() => createTask('   '), (err) => err.code === 'TITLE_REQUIRED');
});

// ---------------------------------------------------------------------------
// 覆盖 1：标签 / 优先级规整
// ---------------------------------------------------------------------------

test('[覆盖1] normalizeTags：trim / 去空 / 去重 / 单标签≤30 截断 / 最多 10 个', () => {
  assert.deepEqual(normalizeTags([' 前端 ', '', '前端', '后端']), ['前端', '后端']);
  assert.deepEqual(normalizeTags('前端, 后端 ，前端'), ['前端', '后端'], '兼容中英文逗号');
  assert.deepEqual(normalizeTags(undefined), []);
  assert.deepEqual(normalizeTags(null), []);
  assert.deepEqual(normalizeTags(42), []);
  assert.deepEqual(normalizeTags('   '), []);
  assert.deepEqual(normalizeTags(['字'.repeat(31)]), ['字'.repeat(30)], '>30 截断到 30');
  assert.deepEqual(normalizeTags(['字'.repeat(30)]), ['字'.repeat(30)], '=30 保留');
  assert.equal(normalizeTags(Array.from({ length: 20 }, (_, i) => 't' + i)).length, 10, '最多 10 个');
  assert.deepEqual(normalizeTags([1, 'a', {}, 'b', null]), ['a', 'b'], '非字符串项丢弃');
});

test('[覆盖1] normalizePriority：忽略大小写与空白，非法一律回落 medium', () => {
  assert.equal(normalizePriority('high'), 'high');
  assert.equal(normalizePriority(' LOW '), 'low');
  assert.equal(normalizePriority('Medium'), 'medium');
  assert.equal(normalizePriority('urgent'), 'medium');
  assert.equal(normalizePriority(''), 'medium');
  assert.equal(normalizePriority(undefined), 'medium');
  assert.equal(normalizePriority(null), 'medium');
  assert.equal(normalizePriority(3), 'medium');
});

// ---------------------------------------------------------------------------
// 覆盖 2、3：创建与更新
// ---------------------------------------------------------------------------

test('[覆盖2/3] createTask：默认值、trim、id/时间戳形态正确', () => {
  const task = createTask({ title: '  写文档  ', tags: '前端, 前端, 后端' });

  assert.equal(task.title, '写文档', '标题应 trim');
  assert.equal(task.status, 'todo', '默认状态 todo');
  assert.equal(task.priority, 'medium', '默认优先级 medium');
  assert.deepEqual(task.tags, ['前端', '后端']);
  assert.match(task.id, /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/, 'id 应为 UUID');
  assert.equal(task.createdAt, task.updatedAt, '创建时两个时间戳相同');
  assert.equal(new Date(task.createdAt).toISOString(), task.createdAt, 'createdAt 应为 ISO8601');

  const fixed = createTask({ title: 'x', priority: 'high', status: 'doing' }, new Date('2026-01-01T00:00:00.000Z'));
  assert.equal(fixed.priority, 'high');
  assert.equal(fixed.status, 'doing');
  assert.equal(fixed.createdAt, '2026-01-01T00:00:00.000Z', 'now 可注入');
});

test('[覆盖3] updateTask：就地更新、返回同一引用、只识别四个白名单字段、刷新 updatedAt', () => {
  const task = createTask({ title: '原标题', priority: 'low', tags: ['a'] }, new Date('2026-01-01T00:00:00.000Z'));
  const originalId = task.id;
  const originalCreatedAt = task.createdAt;

  const returned = updateTask(
    task,
    { title: '新标题', priority: 'high', tags: 'x, y', status: 'doing', id: 'hack', createdAt: '1999' },
    new Date('2026-02-02T00:00:00.000Z'),
  );

  assert.equal(returned, task, 'updateTask 就地更新并返回同一对象引用');
  assert.equal(task.title, '新标题');
  assert.equal(task.priority, 'high');
  assert.deepEqual(task.tags, ['x', 'y']);
  assert.equal(task.status, 'doing');
  assert.equal(task.id, originalId, 'id 不可被覆盖');
  assert.equal(task.createdAt, originalCreatedAt, 'createdAt 不可被覆盖');
  assert.equal(task.updatedAt, '2026-02-02T00:00:00.000Z', 'updatedAt 应用注入时间刷新');
  assert.notEqual(task.updatedAt, task.createdAt, 'updatedAt 应变化');
});

test('[覆盖3] updateTask：空白标题抛 TITLE_REQUIRED，非法状态抛 INVALID_STATUS，非法任务对象抛 INVALID_TASK', () => {
  const task = createTask({ title: '有效标题' });
  assert.throws(() => updateTask(task, { title: '   ' }), (err) => err.code === 'TITLE_REQUIRED');
  assert.throws(() => updateTask(task, { title: 42 }), (err) => err.code === 'TITLE_REQUIRED');
  assert.throws(() => updateTask(task, { title: 'a'.repeat(201) }), (err) => err.code === 'TITLE_TOO_LONG');
  assert.throws(() => updateTask(task, { status: 'xx' }), (err) => err.code === 'INVALID_STATUS');
  assert.throws(() => updateTask(task, { status: 3 }), (err) => err.code === 'INVALID_STATUS');
  assert.throws(() => updateTask(null, { status: 'doing' }), (err) => err.code === 'INVALID_TASK');

  // 未提供 title 时不应因 title 报错（patch 为空对象也允许）
  assert.doesNotThrow(() => updateTask(task, {}));
});

// ---------------------------------------------------------------------------
// 覆盖 5：筛选与排序
// ---------------------------------------------------------------------------

function fixtureTasks() {
  return [
    { id: '1', title: '写 README', status: 'todo', priority: 'low', tags: ['文档'], createdAt: '2026-01-01T00:00:00.000Z' },
    { id: '2', title: '修 Bug', status: 'doing', priority: 'high', tags: ['前端'], createdAt: '2026-01-02T00:00:00.000Z' },
    { id: '3', title: '发布 <b>版本</b>', status: 'done', priority: 'medium', tags: ['前端', '发布'], createdAt: '2026-01-03T00:00:00.000Z' },
  ];
}

test('[覆盖5] filterTasks：按 status / tag / q（大小写不敏感、命中标题或标签），空值不筛选', () => {
  const tasks = fixtureTasks();

  assert.equal(filterTasks(tasks, { status: 'doing' }).length, 1);
  assert.equal(filterTasks(tasks, { status: 'all' }).length, 3, 'all 等同不筛选');
  assert.equal(filterTasks(tasks, { tag: '前端' }).length, 2);
  assert.equal(filterTasks(tasks, { tag: 'all' }).length, 3);
  assert.equal(filterTasks(tasks, { tag: '不存在' }).length, 0);
  assert.equal(filterTasks(tasks, { q: 'bug' }).length, 1, '大小写不敏感');
  assert.equal(filterTasks(tasks, { q: 'BUG' }).length, 1);
  assert.equal(filterTasks(tasks, { q: '版本' }).length, 1, '可命中标题中的子串');
  assert.equal(filterTasks(tasks, { q: '发布' }).length, 1, '可命中标签');
  assert.equal(filterTasks(tasks, { q: '前端' }).length, 2, '标签命中');
  assert.equal(filterTasks(tasks, {}).length, 3);
  assert.equal(filterTasks(tasks, { status: 'done', tag: '前端', q: 'version' }).length, 0, '多条件为 AND');

  const out = filterTasks(tasks, { status: 'todo' });
  assert.notEqual(out, tasks, '应返回新数组');
  assert.deepEqual(tasks.map((t) => t.id), ['1', '2', '3'], '不应改动入参');
});

test('[覆盖5] sortTasks：createdAt / priority × asc / desc，稳定且不改动入参', () => {
  const tasks = fixtureTasks();

  assert.deepEqual(sortTasks(tasks, { sort: 'createdAt', order: 'asc' }).map((t) => t.id), ['1', '2', '3']);
  assert.deepEqual(sortTasks(tasks, { sort: 'createdAt', order: 'desc' }).map((t) => t.id), ['3', '2', '1']);
  assert.deepEqual(sortTasks(tasks, { sort: 'priority', order: 'asc' }).map((t) => t.id), ['1', '3', '2']);
  assert.deepEqual(sortTasks(tasks, { sort: 'priority', order: 'desc' }).map((t) => t.id), ['2', '3', '1']);

  // 默认：createdAt + desc
  assert.deepEqual(sortTasks(tasks).map((t) => t.id), ['3', '2', '1']);
  // 不可识别值回落默认
  assert.deepEqual(sortTasks(tasks, { sort: 'nope', order: 'nope' }).map((t) => t.id), ['3', '2', '1']);

  const out = sortTasks(tasks, { sort: 'priority', order: 'asc' });
  assert.notEqual(out, tasks, '应返回新数组');
  assert.deepEqual(tasks.map((t) => t.id), ['1', '2', '3'], '不应改动入参顺序');
});

test('[覆盖5] sortTasks：同优先级时按 createdAt 再按 id 确定性排序', () => {
  const list = [
    { id: 'b', title: 'b', priority: 'high', createdAt: '2026-01-02T00:00:00.000Z' },
    { id: 'a', title: 'a', priority: 'high', createdAt: '2026-01-02T00:00:00.000Z' },
    { id: 'c', title: 'c', priority: 'high', createdAt: '2026-01-01T00:00:00.000Z' },
  ];
  assert.deepEqual(sortTasks(list, { sort: 'priority', order: 'asc' }).map((t) => t.id), ['c', 'a', 'b']);
  assert.deepEqual(sortTasks(list, { sort: 'priority', order: 'desc' }).map((t) => t.id), ['b', 'a', 'c']);
});

// ---------------------------------------------------------------------------
// 覆盖 6：统计
// ---------------------------------------------------------------------------

test('[覆盖6] computeStats：total / byStatus 恒含三键 / byTag 计数正确', () => {
  const tasks = fixtureTasks();
  const stats = computeStats(tasks);

  assert.equal(stats.total, 3);
  assert.deepEqual(stats.byStatus, { todo: 1, doing: 1, done: 1 });
  assert.deepEqual(stats.byTag, { 文档: 1, 前端: 2, 发布: 1 });

  const empty = computeStats([]);
  assert.equal(empty.total, 0);
  assert.deepEqual(empty.byStatus, { todo: 0, doing: 0, done: 0 }, '无任务时三键仍在且为 0');
  assert.deepEqual(empty.byTag, {});

  assert.deepEqual(computeStats(null).byStatus, { todo: 0, doing: 0, done: 0 }, '非数组入参安全');
});

'use strict';

/**
 * 交付级测试套件 02：本地 JSON 存储（src/store.js）。
 *
 * 覆盖清单：4（store 语义）、7（持久化）、8（原子写的落盘侧）、9（损坏备份的落盘侧）。
 * 每例自建 fs.mkdtemp 临时目录，例后清理，不触碰项目 data/。
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const storeModule = require('../src/store.js');
const { createStore } = storeModule;

function tmpDir(prefix) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
  return dir;
}

// ---------------------------------------------------------------------------

test('[契约] store 导出形态：createStore 可用，且兼容 require(...)({...}) 直接调用', async (t) => {
  assert.equal(typeof createStore, 'function', 'createStore 应为函数');
  assert.equal(typeof storeModule, 'function', '模块本身也应可直接调用（兼容写法）');

  const dir = tmpDir('kanban-store-export-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const dataFile = path.join(dir, 'tasks.json');

  const viaNamed = createStore({ dataFile });
  const viaCall = storeModule({ dataFile });
  assert.equal(typeof viaNamed.list, 'function');
  assert.equal(typeof viaCall.list, 'function');
  assert.equal(viaNamed.dataFile, dataFile);
  assert.equal(path.isAbsolute(viaNamed.dataFile), true, 'dataFile 应为绝对路径');
});

test('[覆盖4] store 增删改查：list/get/create/update/remove 语义与 NOT_FOUND', async (t) => {
  const dir = tmpDir('kanban-store-crud-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const dataFile = path.join(dir, 'tasks.json');

  const store = createStore({ dataFile });
  assert.deepEqual(store.list(), []);
  assert.equal(store.warning, null, '正常文件无告警');
  assert.equal(store.get('不存在'), null, 'get 不存在返回 null');

  const a = store.create({ title: '任务 A', priority: 'high', tags: ['前端'] });
  const b = store.create({ title: '任务 B' });
  assert.equal(store.list().length, 2);
  assert.equal(store.get(a.id).title, '任务 A');

  store.update(a.id, { status: 'done', title: '任务 A2' });
  assert.equal(store.get(a.id).status, 'done');
  assert.equal(store.get(a.id).title, '任务 A2');

  assert.throws(() => store.update('不存在', { title: 'x' }), (err) => err.code === 'NOT_FOUND');
  assert.throws(() => store.remove('不存在'), (err) => err.code === 'NOT_FOUND');
  assert.throws(() => store.create({ title: '   ' }), (err) => err.code === 'TITLE_REQUIRED');

  const removed = store.remove(b.id);
  assert.equal(removed.id, b.id, 'remove 返回被删除任务');
  assert.equal(store.list().length, 1);
  assert.equal(store.get(b.id), null);
});

test('[覆盖4] store 返回副本：外部改动不影响内部状态（tags 深拷贝）', async (t) => {
  const dir = tmpDir('kanban-store-clone-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const dataFile = path.join(dir, 'tasks.json');

  const store = createStore({ dataFile });
  const created = store.create({ title: '原任务', tags: ['a'] });

  created.tags.push('被篡改');
  created.title = '被篡改';
  assert.deepEqual(store.get(created.id).tags, ['a'], 'tags 必须是副本');
  assert.equal(store.get(created.id).title, '原任务');

  const listed = store.list();
  listed[0].tags.push('列表篡改');
  assert.deepEqual(store.get(created.id).tags, ['a'], 'list() 也必须返回副本');
});

// ---------------------------------------------------------------------------
// 覆盖 7：持久化
// ---------------------------------------------------------------------------

test('[覆盖7] 持久化：新 store 实例读回任务仍在（含状态与标签）', async (t) => {
  const dir = tmpDir('kanban-store-persist-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const dataFile = path.join(dir, 'tasks.json');

  const store1 = createStore({ dataFile });
  const task = store1.create({ title: '持久化任务', priority: 'high', tags: ['持久'] });
  store1.update(task.id, { status: 'doing' });

  assert.equal(fs.existsSync(dataFile), true, '写入后数据文件应存在');
  const onDisk = JSON.parse(fs.readFileSync(dataFile, 'utf8'));
  assert.equal(Array.isArray(onDisk), true, '默认落盘为任务数组');
  assert.equal(onDisk.length, 1);

  const store2 = createStore({ dataFile });
  assert.equal(store2.warning, null);
  assert.equal(store2.list().length, 1);
  assert.equal(store2.list()[0].title, '持久化任务');
  assert.equal(store2.list()[0].status, 'doing');
  assert.deepEqual(store2.list()[0].tags, ['持久']);
});

test('[覆盖7] 数据文件缺失 / 为空：视为空列表，无告警，不报错', async (t) => {
  const dir = tmpDir('kanban-store-empty-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));

  const missing = createStore({ dataFile: path.join(dir, 'nope', 'tasks.json') });
  assert.deepEqual(missing.list(), []);
  assert.equal(missing.warning, null);

  const emptyFile = path.join(dir, 'empty.json');
  fs.writeFileSync(emptyFile, '   \n  ', 'utf8');
  const blank = createStore({ dataFile: emptyFile });
  assert.deepEqual(blank.list(), []);
  assert.equal(blank.warning, null);
});

test('[覆盖7] 兼容 {"tasks":[...]} 包装形式读取', async (t) => {
  const dir = tmpDir('kanban-store-wrapper-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const dataFile = path.join(dir, 'tasks.json');
  fs.writeFileSync(dataFile, JSON.stringify({
    tasks: [{ id: 'w1', title: '包装任务', status: 'done', priority: 'low', tags: ['x'], createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:00:00.000Z' }],
  }), 'utf8');

  const store = createStore({ dataFile });
  assert.equal(store.warning, null);
  assert.equal(store.list().length, 1);
  assert.equal(store.list()[0].title, '包装任务');
  assert.equal(store.list()[0].id, 'w1');
});

test('[覆盖7/9] 条目级不合法（缺 title）被跳过，不触发整文件备份', async (t) => {
  const dir = tmpDir('kanban-store-skip-');
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const dataFile = path.join(dir, 'tasks.json');
  fs.writeFileSync(dataFile, JSON.stringify([
    { id: 'ok', title: '有效条目', status: 'todo', priority: 'low', tags: [], createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:00:00.000Z' },
    { id: 'bad', status: 'todo', priority: 'low' },
    null,
    'not-an-object',
  ]), 'utf8');

  const store = createStore({ dataFile });
  assert.equal(store.warning, null, '条目级不合法不应触发整文件告警');
  assert.equal(store.list().length, 1, '仅保留合法条目');
  assert.equal(store.list()[0].id, 'ok');
  const backups = fs.readdirSync(dir).filter((f) => f.startsWith('tasks.json.corrupt-'));
  assert.deepEqual(backups, [], '不应产生 corrupt 备份');
});

