// 测试者：KANBAN-DEF-001 复跑专项 —— 两种客户端各验一次 413
// 用法: node temp/测试者/probe-413-v2.cjs
'use strict';
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');
const { createServer } = require('../../src/server.js');

const OVERSIZED = JSON.stringify({ title: '大任务', pad: 'x'.repeat(1024 * 1024 + 64) });

function rawHttp413(port) {
  return new Promise((resolve) => {
    const req = http.request(
      { host: '127.0.0.1', port, path: '/api/tasks', method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(OVERSIZED) } },
      (res) => {
        let raw = '';
        res.setEncoding('utf8');
        res.on('data', (c) => { raw += c; });
        res.on('end', () => resolve({ status: res.statusCode, raw }));
      },
    );
    req.on('error', (err) => resolve({ netError: err.code || err.message }));
    req.end(OVERSIZED);
  });
}

async function fetch413(url) {
  try {
    const res = await fetch(`${url}/api/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: OVERSIZED,
    });
    const text = await res.text();
    return { status: res.status, raw: text };
  } catch (err) {
    return { netError: err.code || err.message };
  }
}

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kanban-probe413-'));
  const dataFile = path.join(dir, 'tasks.json');
  const started = await createServer({ dataFile, port: 0 });
  const out = {};
  try {
    // 1) fetch (undici)
    out.fetch = await fetch413(started.url);
    // 2) 原始 node:http 客户端
    out.rawHttp = await rawHttp413(started.port);

    // 3) 零副作用：无任务落库
    const listRes = await fetch(`${started.url}/api/tasks`);
    const list = await listRes.json();
    out.tasksAfter = list.tasks.length;

    // 4) 目录残留检查
    out.dirEntries = fs.readdirSync(dir);
    out.tmpResidue = out.dirEntries.filter((f) => f.includes('.tmp-') || f.startsWith('tmp-'));
    out.dataFileExists = fs.existsSync(dataFile);
  } finally {
    await started.close();
    fs.rmSync(dir, { recursive: true, force: true });
  }

  const parse = (r) => {
    if (!r) return null;
    if (r.netError) return { netError: r.netError };
    let code = null;
    try { code = JSON.parse(r.raw).error.code; } catch (_) { /* ignore */ }
    return { status: r.status, code, raw: r.raw };
  };

  console.log(JSON.stringify({
    client_fetch_undici: parse(out.fetch),
    client_node_http_raw: parse(out.rawHttp),
    tasks_after_oversized: out.tasksAfter,
    dir_entries: out.dirEntries,
    tmp_residue: out.tmpResidue,
    datafile_created: out.dataFileExists,
  }, null, 2));
})();

