// 测试者：修复后回归专项（逐项显式断言 + 1MB 边界语义）
// 用法: node temp/测试者/probe-regression-v2.cjs
'use strict';
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const assert = require('node:assert/strict');
const { createServer } = require('../../src/server.js');

const results = [];
async function check(name, fn) {
  try { await fn(); results.push({ name, ok: true }); }
  catch (e) { results.push({ name, ok: false, detail: e.message }); }
}

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kanban-regress-'));
  const dataFile = path.join(dir, 'tasks.json');
  const { url, port, server, close } = await createServer({ dataFile, port: 0 });

  try {
    // 绑定
    await check('只绑 127.0.0.1', () => assert.equal(server.address().address, '127.0.0.1'));

    // TITLE_REQUIRED
    await check('空白标题 400 TITLE_REQUIRED', async () => {
      const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: '   ' }) });
      assert.equal(r.status, 400);
      assert.equal((await r.json()).error.code, 'TITLE_REQUIRED');
    });

    // BAD_JSON
    await check('BAD_JSON 400', async () => {
      const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{oops' });
      assert.equal(r.status, 400);
      assert.equal((await r.json()).error.code, 'BAD_JSON');
    });

    // METHOD_NOT_ALLOWED
    await check('METHOD_NOT_ALLOWED 405', async () => {
      const r = await fetch(`${url}/api/tasks`, { method: 'DELETE' });
      assert.equal(r.status, 405);
      assert.equal((await r.json()).error.code, 'METHOD_NOT_ALLOWED');
    });

    // NOT_FOUND
    await check('NOT_FOUND 404', async () => {
      const r = await fetch(`${url}/api/tasks/不存在`);
      assert.equal(r.status, 404);
      assert.equal((await r.json()).error.code, 'NOT_FOUND');
    });

    // 正常增删改查 + 导出
    let id;
    await check('POST 201 + 导出附件头', async () => {
      const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: '回归任务', tags: ['x'] }) });
      assert.equal(r.status, 201);
      id = (await r.json()).task.id;
      const ex = await fetch(`${url}/api/export`);
      assert.equal(ex.status, 200);
      assert.match(ex.headers.get('content-disposition'), /^attachment; filename="kanban-export-\d{8}\.json"$/);
      assert.equal((await ex.json()).count, 1);
    });

    await check('DELETE {ok:true} 且再次删除 404', async () => {
      const d1 = await fetch(`${url}/api/tasks/${encodeURIComponent(id)}`, { method: 'DELETE' });
      assert.equal(d1.status, 200);
      assert.deepEqual(await d1.json(), { ok: true });
      const d2 = await fetch(`${url}/api/tasks/${encodeURIComponent(id)}`, { method: 'DELETE' });
      assert.equal(d2.status, 404);
    });

    // 1MB 边界语义：恰好 1MiB（可解析 JSON）应通过；1MiB+1 应 413
    await check('恰好 1MiB body 仍被接受', async () => {
      const title = '边界任务';
      const overhead = JSON.stringify({ title, pad: '' }).length; // {"title":"边界任务","pad":""}
      const padLen = 1024 * 1024 - overhead;
      const body = JSON.stringify({ title, pad: 'x'.repeat(padLen) });
      assert.equal(Buffer.byteLength(body), 1024 * 1024, 'body 应恰为 1MiB');
      const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body });
      assert.equal(r.status, 201, '恰好 1MiB 不得被 413');
    });

    await check('1MiB+1 body 触发 413', async () => {
      const title = '溢出任务';
      const overhead = JSON.stringify({ title, pad: '' }).length;
      const padLen = 1024 * 1024 + 1 - overhead;
      const body = JSON.stringify({ title, pad: 'x'.repeat(padLen) });
      assert.equal(Buffer.byteLength(body), 1024 * 1024 + 1);
      const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body });
      assert.equal(r.status, 413);
      assert.equal((await r.json()).error.code, 'PAYLOAD_TOO_LARGE');
    });
  } finally {
    await close();
    fs.rmSync(dir, { recursive: true, force: true });
  }

  console.log(JSON.stringify(results, null, 2));
  const failed = results.filter((r) => !r.ok);
  console.log(`--- 回归小结: ${results.length - failed.length}/${results.length} 通过 ---`);
  process.exitCode = failed.length ? 1 : 0;
})();

