// 1MB 边界语义：恰好 1MiB（可解析 JSON）应通过；1MiB+1 应 413
// 注意：用 Buffer.byteLength 计算字节数（CJK/UTF-8），而非 .length（UTF-16 单元）。
const makeBody = (targetBytes) => {
  const title = '边界任务';
  const baseBytes = Buffer.byteLength(JSON.stringify({ title, pad: '' })); // pad 值为空串占 2 字节
  const padLen = targetBytes - baseBytes + 2; // 把空串 2 字节换成 padLen 个 'x'
  const body = JSON.stringify({ title, pad: 'x'.repeat(padLen) });
  assert.equal(Buffer.byteLength(body), targetBytes, `构造的 body 应恰为 ${targetBytes} 字节`);
  return body;
};

await check('恰好 1MiB body 仍被接受', async () => {
  const body = makeBody(1024 * 1024);
  const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body });
  assert.equal(r.status, 201, '恰好 1MiB 不得被 413');
});

await check('1MiB+1 body 触发 413', async () => {
  const body = makeBody(1024 * 1024 + 1);
  const r = await fetch(`${url}/api/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body });
  assert.equal(r.status, 413);
  assert.equal((await r.json()).error.code, 'PAYLOAD_TOO_LARGE');
});

